function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function j($v):string{return json_encode($v,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}function n($v):string{return is_numeric($v)?(abs($v)>0&&abs($v)<.0001?sprintf('%.4e',$v):rtrim(rtrim(sprintf('%.6f',$v),'0'),'.')):(string)$v;}
function security():void{header_remove('X-Powered-By');if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-src 'none'; frame-ancestors 'none'; form-action 'self'");header('Permissions-Policy: camera=(), microphone=(), geolocation=()');}
