able()):?><a href="/explore/">Explore 3D</a><?php endif;?><a href="/evidence/">Evidence</a><?php if(\bsp_legacy_available()):?><a href="/agents/">Agents</a><?php endif;?></nav><a class="arc" href="https://arcsecs.com/read-book/">ArcSecs ↗</a></div></header><nav class="museum-crossnav" aria-label="Museum exhibits"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/" aria-current="true">Foundations</a><a href="/evidence/">Evidence</a><a href="/research/">Workspace</a><a href="/model-comparison/">Compare</a><a href="/timeline/">Timeline</a><a href="/global/">Languages</a><a href="/offline/">Offline</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a></nav><main id="main" class="wrap"><div class="crumb"><a href="/">Home</a> / <a href="/foundations/">Foundations</a><?=$path!==ROOT?' / '.h($title):''?></div><?php }
