function hub_page():void{if(!in_array($_SERVER['REQUEST_METHOD']??'GET',['GET','HEAD'],true)){http_response_code(405);header('Allow: GET, HEAD');return;}start('The twelve foundations experience','Explore all twelve exact ArcSecs research premises through explanations, reference physics and interactive numerical controls.',ROOT,[['@type'=>'ItemList','itemListElement'=>array_map(fn($l)=>['@type'=>'ListItem','position'=>$l['number'],'name'=>$l['title'],'url'=>$l['url']],array_values(lessons()))]]);?><section class="hero"><img src="/foundations/assets/banner.webp" alt="Beyond Spacetime cosmic exploration" width="1400" height="600"><div><span class="eyebrow">THE TWELVE FOUNDATIONS · v1.3.0</span><h1>Question the universe.<br><span class="gold">Test the possibilities.</span></h1><p class="lead">Twelve research commitments. Twelve interactive investigations. Begin with an intuitive explanation, compare the conventional reference, then inspect the mathematics and the evidence that would be needed.</p><a class="button" href="/foundations/photon-mass/">Start with light →</a> <a class="button secondary" href="#all">Explore all twelve</a></div></section><section class="stats"><div><strong>12</strong><span>Exact charter premises</span></div><div><strong>12</strong><span>Numerical controls</span></div><div><strong>3</strong><span>Learning layers per lesson</span></div><div><strong>0</strong><span>External software libraries</span></div></section><section class="notice"><h2>The charter is the agenda, not the verdict.</h2><p>The statements below preserve the wording of Scientific Review 6.0, §2 (printed pp. 6–7). They are the investigator’s premises. Each lesson separates the original claim, established reference physics, conditional calculations and necessary empirical tests.</p><a href="https://arcsecs.com/read-scientific-paper/">Read the authoritative review ↗</a></section><section id="all"><div class="section-heading"><h2>Choose a foundation</h2><span id="progress">Progress available on this device</span></div><div class="grid"><?php foreach(lessons() as $l):?><article class="card" data-lesson="<?=h($l['slug'])?>"><span class="number"><?=sprintf('%02d',$l['number'])?></span><span class="eyebrow">RESEARCH PREMISE</span><h3><a href="<?=ROOT.h($l['slug'])?>/"><?=h($l['title'])?></a></h3><p class="quote"><?=h($l['statement'])?></p><p><?=h($l['answer'])?></p><a class="text-link" href="<?=ROOT.h($l['slug'])?>/">Investigate →</a></article><?php endforeach;?></div></section><section class="notice"><h2>Built for people and machine intelligence</h2><p>The <a href="/foundations/catalog.json">JSON lesson catalog</a> provides the exact charter, educational interpretation, parameter bounds and source references. The <a href="/foundations/api/">foundation API</a> supports validated calculations and a bounded AG-UI-style event stream without an external model or SDK.</p></section><?php page_end();}
function chart(array $r):void{$xs=array_column($r['rows'],0);$xmin=min($xs);$xmax=max($xs);$ys=[];foreach($r['rows'] as $row)foreach(array_slice($row,1) as $y)$ys[]=$y;$lo=min(0,min($ys));$hi=max(0,max($ys));if($hi==$lo)$hi=$lo+1;$x=fn($v)=>62+($v-$xmin)/max(1e-20,$xmax-$xmin)*620;$y=fn($v)=>246-($v-$lo)/($hi-$lo)*214;?><figure class="chart-box"><svg class="chart" viewBox="0 0 720 300" role="img" aria-label="<?=h($r['xLabel'].' versus '.implode(', ',$r['series']))?>"><?php for($i=0;$i<=4;$i++):$Y=32+$i*53.5;$X=62+$i*155;?><line class="gridline" x1="62" x2="682" y1="<?=$Y?>" y2="<?=$Y?>"/><text x="56" y="<?=$Y+4?>" text-anchor="end"><?=h(n($hi-($hi-$lo)*$i/4))?></text><text x="<?=$X?>" y="264" text-anchor="middle"><?=h(n($xmin+($xmax-$xmin)*$i/4))?></text><?php endfor;foreach($r['series'] as $i=>$s):$pts=[];foreach($r['rows'] as $row)$pts[]=sprintf('%.2f,%.2f',$x($row[0]),$y($row[$i+1]));?><polyline class="line l<?=$i?>" points="<?=implode(' ',$pts)?>"/><?php endforeach;?><text x="372" y="289" text-anchor="middle"><?=h($r['xLabel'])?></text></svg><figcaption><?php foreach($r['series'] as $i=>$s):?><span><i class="swatch l<?=$i?>"></i><?=h($s)?></span><?php endforeach;?></figcaption></figure><?php }
function evidence(array $r,array $control):void{?><div class="metrics"><?php foreach($r['metrics'] as $m):?><div><span><?=h($m['label'])?></span><strong><?=h(n($m['value']))?> <small><?=h($m['unit'])?></small></strong></div><?php endforeach;?></div><?php chart($r);?><details><summary>Compare selected result with negative/reference control</summary><div class="table-scroll"><table><thead><tr><th>Quantity</th><th>Selected</th><th>Control</th><th>Difference</th></tr></thead><tbody><?php foreach($r['metrics'] as $i=>$m):?><tr><th scope="row"><?=h($m['label'])?></th><td><?=h(n($m['value']))?></td><td><?=h(n($control['metrics'][$i]['value']))?></td><td><?=h(n($m['value']-$control['metrics'][$i]['value']))?></td></tr><?php endforeach;?></tbody></table></div></details><details><summary>Numerical samples (first 8 and final; full JSON export)</summary><div class="table-scroll"><table><thead><tr><?php foreach(array_merge([$r['xLabel']],$r['series']) as $s):?><th scope="col"><?=h($s)?></th><?php endforeach;?></tr></thead><tbody><?php foreach(array_merge(array_slice($r['rows'],0,8),[end($r['rows'])]) as $row):?><tr><?php foreach($row as $v):?><td><?=h(n($v))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details><?php }
function lesson_page(string $id):void{$l=lessons()[$id];$method=$_SERVER['REQUEST_METHOD']??'GET';if(!in_array($method,['GET','HEAD','POST'],true)){http_response_code(405);header('Allow: GET, HEAD, POST');return;}$error='';try{$p=$method==='POST'?($_POST['p']??[]):[];if(!is_array($p))throw new InvalidArgumentException('Invalid parameters.');$r=solve($id,$p);}catch(InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage().' Default result shown.';$r=solve($id);}$c=solve($id,array_replace($r['parameters'],$l['control']));$path=ROOT.$id.'/';start($l['title'],$l['answer'],$path,[['@type'=>'LearningResource','@id'=>ORIGIN.$path.'#lesson','name'=>$l['title'],'description'=>$l['answer'],'educationalLevel'=>['Beginner','Intermediate','Advanced'],'learningResourceType'=>'Interactive lesson','citation'=>['@type'=>'CreativeWork','name'=>'ArcSecs Scientific Review 6.0','url'=>$l['source']['url']]],['@type'=>'BreadcrumbList','itemListElement'=>[['@type'=>'ListItem','position'=>1,'name'=>'Home','item'=>ORIGIN.'/'],['@type'=>'ListItem','position'=>2,'name'=>'Foundations','item'=>ORIGIN.ROOT],['@type'=>'ListItem','position'=>3,'name'=>$l['title'],'item'=>ORIGIN.$path]]]],$method==='POST');?><section class="intro"><span class="eyebrow">FOUNDATION <?=sprintf('%02d',$l['number'])?> / 12 · RESEARCH PREMISE</span><h1><?=h($l['title'])?></h1><p class="lead"><?=h($l['answer'])?></p><blockquote><small>Exact charter statement</small><?=h($l['statement'])?></blockquote><div class="chips"><a href="#explorer">Explorer</a><a href="#investigator">Investigator</a><a href="#researcher">Researcher</a></div></section><section id="explorer" class="panel"><span class="eyebrow">01 · EXPLORER</span><h2>Understand the idea</h2><p><?=h($l['explorer'])?></p><div class="split"><div><h3>Established reference</h3><p><?=h($l['standard'])?></p></div><div><h3>ArcSecs investigation</h3><p><?=h($l['candidate'])?></p></div></div></section><section id="investigator" class="section"><span class="eyebrow">02 · INVESTIGATOR</span><h2>Change the assumptions. Inspect the result.</h2><p class="formula"><?=h($l['equation'])?></p><div class="workbench"><aside class="panel"><h3>Model parameters</h3><form id="lesson-form" method="post" action="<?=h($path)?>"><?php foreach($l['params'] as $d):?><div class="field"><label for="p-<?=h($d['key'])?>"><?=h($d['label'].' '.$d['unit'])?></label><input required type="number" name="p[<?=h($d['key'])?>]" id="p-<?=h($d['key'])?>" min="<?=$d['min']?>" max="<?=$d['max']?>" step="any" value="<?=h($r['parameters'][$d['key']])?>"><small>Range <?=$d['min']?>–<?=$d['max']?></small></div><?php endforeach;?><button class="button" type="submit">Calculate</button> <a class="button secondary" href="<?=h($path)?>">Reset</a><button type="button" id="control" class="button secondary js" hidden>Load reference control</button></form><p id="status" role="status"><?=h($error?:'Ready. Results reflect the submitted parameters.')?></p><div class="notice"><strong>Try this</strong><p><?=h($l['challenge'])?></p></div></aside><div class="panel"><h3>Computed evidence</h3><div id="evidence"><?php evidence($r,$c);?></div><div class="actions"><button type="button" id="export" class="button secondary js" hidden>Export complete JSON</button><button type="button" id="csv" class="button secondary js" hidden>Export CSV</button></div><script id="initial" type="application/json"><?=j(['lesson'=>$id,'control'=>$l['control'],'result'=>$r,'reference'=>$c])?></script></div></div></section><?php if(in_array($id,['constant-time','when','spacetime'],true)):?><section class="panel section"><h2>Universal progression and the dinner deadline</h2><p>Under the ArcSecs premise, physical processes can accumulate different amounts of change within a consistent universal progression. The home-clock reunion event does not depend on the traveler’s clock count. This is a stipulated interpretation, not evidence against proper-time measurements.</p><a href="/universal-time/dinner/">Try the dinner experiment →</a> · <a href="/universal-time/benchmarks/">Published clock benchmarks →</a></section><?php endif;?><section id="researcher" class="panel"><span class="eyebrow">03 · RESEARCHER</span><h2>What would count as evidence?</h2><p><?=h($l['observation'])?></p><h3>What the calculation does not establish</h3><p><?=h($l['limitation'])?></p><p class="source"><strong>Research source:</strong> <?=h($l['reference'])?>. <a href="https://arcsecs.com/read-scientific-paper/">Read Review 6.0 ↗</a> · <a href="https://arcsecs.com/read-book/">Read the book ↗</a></p><div class="chips"><a href="/research/">Research workspace →</a><a href="/model-comparison/">Model comparison →</a><?php if(\bsp_legacy_available()):?><a href="/concepts/<?=h($l['topic'])?>/">Related concept →</a><?php endif;?><?php if(\bsp_legacy_available()):?><a href="/labs/<?=h($l['lab'])?>/">Extended laboratory →</a><?php endif;?><?php if(\bsp_legacy_available()):?><a href="/compare/?experiment=<?=h($l['lab'])?>">Compare cases →</a><?php endif;?></div></section><section class="panel section"><h2>Check your understanding</h2><details><summary>Reveal the self-check question and answer</summary><p><?=h($l['quiz'])?></p></details><label class="completion"><input id="complete" type="checkbox" data-lesson="<?=h($id)?>"> Mark this foundation as completed on this device</label></section><div class="prevnext"><?php $all=array_values(lessons());if($l['number']>1):$prev=$all[$l['number']-2];?><a class="button secondary" href="<?=ROOT.h($prev['slug'])?>/">← Foundation <?=$prev['number']?></a><?php endif;?><a href="/foundations/">All twelve</a><?php if($l['number']<12):$next=$all[$l['number']];?><a class="button" href="<?=ROOT.h($next['slug'])?>/">Foundation <?=$next['number']?> →</a><?php endif;?></div><?php page_end();}
